// Typed wrappers around Tauri commands. One function per command, importing payload types only from
// src/bindings/ (generated by ts-rs, never hand-edited). See docs/ARCHITECTURE.md §6 and D-012.
import { invoke, isTauri } from "@tauri-apps/api/core";
import type { AppInfo } from "@/bindings/AppInfo";
import type { InstalledView } from "@/bindings/InstalledView";
import type { JobInfo } from "@/bindings/JobInfo";
import type { Leftover } from "@/bindings/Leftover";
import type { LunaError } from "@/bindings/LunaError";
import type { Project } from "@/bindings/Project";
import type { ProjectDetection } from "@/bindings/ProjectDetection";
import type { ProjectPatch } from "@/bindings/ProjectPatch";
import type { RegistryStatus } from "@/bindings/RegistryStatus";
import type { RuntimesAvailable } from "@/bindings/RuntimesAvailable";
import type { ServiceLogs } from "@/bindings/ServiceLogs";
import type { ServiceRow } from "@/bindings/ServiceRow";
import type { SitesView } from "@/bindings/SitesView";
import type { StartedJob } from "@/bindings/StartedJob";
import type { UsageReport } from "@/bindings/UsageReport";

/** Thrown by every IPC call. Carries the backend's typed error so the UI can map `code` to text. */
export class IpcError extends Error {
  readonly error: LunaError;

  constructor(error: LunaError) {
    super(error.message);
    this.name = "IpcError";
    this.error = error;
  }
}

export function isLunaError(value: unknown): value is LunaError {
  if (typeof value !== "object" || value === null) return false;
  const candidate = value as Record<string, unknown>;
  return typeof candidate.code === "string" && typeof candidate.message === "string";
}

/** Anything a failed `invoke` can reject with, as a `LunaError`. */
export function toLunaError(thrown: unknown): LunaError {
  if (isLunaError(thrown)) return thrown;
  const message = thrown instanceof Error ? thrown.message : String(thrown);
  return { code: "INTERNAL", message };
}

async function call<T>(command: string, args?: Record<string, unknown>): Promise<T> {
  if (!isTauri()) {
    // `pnpm dev` in a plain browser has no backend. Say so instead of failing obscurely.
    throw new IpcError({
      code: "INTERNAL",
      message: "The lunaRun backend is not available. Open the desktop app to use this feature.",
    });
  }
  try {
    return await invoke<T>(command, args);
  } catch (thrown) {
    throw new IpcError(toLunaError(thrown));
  }
}

export const ipc = {
  appInfo: () => call<AppInfo>("app_info"),
  /** Running jobs first, then the newest finished ones. */
  jobsList: () => call<JobInfo[]>("jobs_list"),
  /** `true`: cancellation requested. `false`: the job had already finished. */
  jobCancel: (jobId: string) => call<boolean>("job_cancel", { jobId }),
  /** Every runtime with the versions that can be installed on this computer, and where that list came from. */
  runtimesAvailable: () => call<RuntimesAvailable>("runtimes_available"),
  /** What is installed, by runtime name and newest version first. */
  runtimesInstalled: () => call<InstalledView[]>("runtimes_installed"),
  /** Look for a fresher version list now. Resolves with the status once it has been used. */
  registryRefresh: () => call<RegistryStatus>("registry_refresh"),
  /** Start installing a version as a background job. Progress arrives as `job:*` events. */
  runtimeInstall: (runtime: string, version: string) =>
    call<StartedJob>("runtime_install", { runtime, version }),
  /**
   * Start uninstalling a version as a background job. `deleteData` also deletes the databases of that
   * version; `confirmBoundProjects` says the user saw the projects that use it.
   */
  runtimeUninstall: (
    runtime: string,
    version: string,
    options: { deleteData: boolean; confirmBoundProjects: boolean },
  ) => call<StartedJob>("runtime_uninstall", { runtime, version, ...options }),
  /** What uses a version and where its databases are, for the uninstall dialog. Read-only. */
  runtimeUsage: (runtime: string, version: string) =>
    call<UsageReport>("runtime_usage", { runtime, version }),
  /**
   * What lunaRun can run from what is installed, with each service's state, ports and what its first start will do.
   * Read-only: it writes nothing and takes no port. Live changes arrive as `service:state` events.
   */
  servicesList: () => call<ServiceRow[]>("services_list"),
  /** Services found still running from an earlier session when the app started (looked for once, at startup). */
  servicesLeftovers: () => call<Leftover[]>("services_leftovers"),
  /**
   * Start a service (a row id such as `mysql@8.4`, `php-fcgi@8.3.36` or `caddy`) as a background job named
   * `service:<id>`. The job succeeds when the service runs; a database's first start reports the phase `setup`.
   */
  serviceStart: (id: string) => call<StartedJob>("service_start", { id }),
  /** Stop a service (every worker of a PHP pool) as a background job. Stopping what is not running succeeds. */
  serviceStop: (id: string) => call<StartedJob>("service_stop", { id }),
  /** Stop, then start, as one job. */
  serviceRestart: (id: string) => call<StartedJob>("service_restart", { id }),
  /** "Use another port": give a stopped service other ports than the taken ones, and start it. */
  servicePortReassign: (id: string) => call<StartedJob>("service_port_reassign", { id }),
  /**
   * What a row's services have printed: per service its log sources (`output` first) with the last `tailLines` lines,
   * oldest first. New lines arrive as `service:log` events.
   */
  serviceLogs: (id: string, tailLines: number) =>
    call<ServiceLogs[]>("service_logs", { id, tailLines }),
  /** Take over a service an earlier session left running. */
  serviceAdopt: (id: string) => call<null>("service_adopt", { id }),
  /** End a service an earlier session left running. */
  serviceStopLeftover: (id: string) => call<null>("service_stop_leftover", { id }),
  /** The projects the user added, in the order they were added. Reads the stored list only. */
  projectsList: () => call<Project[]>("projects_list"),
  projectGet: (id: string) => call<Project>("project_get", { id }),
  /**
   * Add a folder (an absolute path) as a project and say what it needs and what to run it with. `INVALID_PATH` when
   * it is not a folder that exists, `PROJECT_EXISTS` when it is already one. Reads the folder; writes nothing in it.
   */
  projectAdd: (path: string) => call<ProjectDetection>("project_add", { path }),
  /** Read the project's folder again ("Re-scan") and say what it needs now. */
  projectDetect: (id: string) => call<ProjectDetection>("project_detect", { id }),
  /** Rename, change the document root, or choose PHP or Node by hand (or back to automatic). `INVALID_INPUT` changes nothing. */
  projectUpdate: (id: string, patch: ProjectPatch) =>
    call<Project>("project_update", { id, patch }),
  /** Forget a project. The folder and its files are never touched. */
  projectRemove: (id: string) => call<null>("project_remove", { id }),
  /**
   * The site of every project (a port each, once its PHP is installed), whether a web server is there to serve it, and
   * why the last change could not be given to Caddy, if it could not.
   */
  sitesList: () => call<SitesView>("sites_list"),
  /** Give Caddy the sites as they are now (the "Try again" after a problem), and say how that went. */
  sitesSync: () => call<SitesView>("sites_sync"),
} as const;
